('077df217-a67f-4ebb-b241-1fc4a39042fc', 'Empanadas integrales con vegetales', 'Whole Wheat Vegetable Empanadas', 'empanadas-integrales-con-vegetales', 45, 32, 5, 'medium', '[{"name": {"en": "whole wheat flour", "es": "harina integral"}, "unit": {"en": "cups", "es": "tazas"}, "quantity": "2", "siboAlert": false}, {"name": {"en": "lemon", "es": "limón"}, "unit": {"en": "", "es": ""}, "quantity": "1", "siboAlert": false}, {"name": {"en": "brewer''s yeast", "es": "levadura de cerveza"}, "unit": {"en": "tablespoon", "es": "cucharada"}, "quantity": "1", "siboAlert": false}, {"name": {"en": "olive oil", "es": "aceite de oliva"}, "unit": {"en": "tablespoons", "es": "cucharadas"}, "quantity": "6", "siboAlert": false}, {"name": {"en": "water", "es": "agua"}, "unit": {"en": "", "es": ""}, "quantity": "necesaria", "siboAlert": false}, {"name": {"en": "sea salt", "es": "sal de mar"}, "unit": {"en": "teaspoon", "es": "cucharadita"}, "quantity": "1", "siboAlert": false}, {"name": {"en": "sesame seeds", "es": "semillas de sésamo"}, "unit": {"en": "", "es": ""}, "quantity": "", "siboAlert": false}, {"name": {"en": "spinach", "es": "espinaca"}, "unit": {"en": "cup", "es": "taza"}, "quantity": "1", "siboAlert": false}, {"name": {"en": "goat cheese", "es": "queso de cabra"}, "unit": {"en": "g", "es": "gr"}, "quantity": "150", "siboAlert": true}, {"name": {"en": "carrot", "es": "zanahoria"}, "unit": {"en": "cup", "es": "taza"}, "quantity": "1/2", "siboAlert": false}, {"name": {"en": "olives", "es": "aceitunas"}, "unit": {"en": "cup", "es": "taza"}, "quantity": "1/2", "siboAlert": false}, {"name": {"en": "walnuts", "es": "nueces"}, "unit": {"en": "cup", "es": "taza"}, "quantity": "1/4", "siboAlert": false}, {"name": {"en": "pepper", "es": "pimienta"}, "unit": {"en": "to taste", "es": "al gusto"}, "quantity": "", "siboAlert": false}]', '[{"type": "active", "order": 1, "instruction": {"en": "Mix all filling ingredients and set aside.", "es": "Mezclar todos los ingredientes del relleno y reservar."}, "durationMinutes": 5}, {"type": "active", "order": 2, "instruction": {"en": "Mix flour, salt, oil, brewer''s yeast, and lemon juice. Add water until a firm dough is formed.", "es": "Mezclar la harina, sal, aceite, levadura de cerveza y jugo de limón. Agregar agua hasta tener una masa firme."}, "durationMinutes": 10}, {"type": "active", "order": 3, "instruction": {"en": "Roll out the dough to 3 or 4 mm thickness.", "es": "Estirar la masa hasta 3 o 4 mm de grosor."}, "durationMinutes": 5}, {"type": "active", "order": 4, "instruction": {"en": "Cut 13 cm circles and fill.", "es": "Cortar círculos de 13 cm y rellenar."}, "durationMinutes": 10}, {"type": "active", "order": 5, "instruction": {"en": "Close the empanadas, brush with olive oil, and sprinkle with sesame seeds.", "es": "Cerrar las empanadas, pincelar con aceite de oliva y espolvorear semillas de sésamo."}, "durationMinutes": 5}, {"type": "active", "order": 6, "instruction": {"en": "Bake at 180 degrees for 30 to 35 minutes.", "es": "Hornear a 180 grados por 30 a 35 minutos."}, "durationMinutes": 32}]', '[{"en": "Empanadas", "es": "Empanadas"}, {"en": "Whole Grain", "es": "Integral"}, {"en": "Vegetables", "es": "Vegetales"}]', '/public/recipes/1775436285028.jpg', '1775436285028.jpg', 'caution', '["queso de cabra"]', 'ocr_image', 'https://api.telegram.org/file/bot8247874972:AAE84_Vvg3dQOX1gz8-L0ijOFBVyBmFD86w/photos/file_12.jpg', 'published', NULL, '2026-04-06 00:44:45.035+00', '2026-04-06 00:44:55.872+00', NULL),
('6db43868-1b59-4a7d-9bee-d8d224354836', 'Arroz con Verduras', 'Vegetable Rice', 'arroz-con-verduras', 35, 25, 4, 'easy', '[{"name": {"en": "Basmati Rice", "es": "Arroz Basmati"}, "unit": {"en": "cups", "es": "tazas"}, "quantity": "2", "siboAlert": false}, {"name": {"en": "Sea Salt", "es": "Sal Marina"}, "unit": {"en": "to taste", "es": "al gusto"}, "quantity": "", "siboAlert": false}, {"name": {"en": "Olive Oil", "es": "Aceite de Oliva"}, "unit": {"en": "", "es": ""}, "quantity": "", "siboAlert": false}, {"name": {"en": "Eggplant", "es": "Berenjena"}, "unit": {"en": "", "es": ""}, "quantity": "1", "siboAlert": false}, {"name": {"en": "Carrots", "es": "Zanahorias"}, "unit": {"en": "", "es": ""}, "quantity": "2", "siboAlert": false}, {"name": {"en": "Red Peppers", "es": "Pimientos Rojos"}, "unit": {"en": "", "es": ""}, "quantity": "2", "siboAlert": false}, {"name": {"en": "Cauliflower", "es": "Coliflor"}, "unit": {"en": "sprigs", "es": "ramitas"}, "quantity": "8", "siboAlert": false}, {"name": {"en": "Green Zucchinis", "es": "Zapallitos Verdes"}, "unit": {"en": "", "es": ""}, "quantity": "2", "siboAlert": false}, {"name": {"en": "Vegetable Broth Powder", "es": "Caldo en Polvo"}, "unit": {"en": "tablespoons", "es": "cucharadas"}, "quantity": "3", "siboAlert": false}, {"name": {"en": "Saffron", "es": "Azafrán"}, "unit": {"en": "teaspoon", "es": "cucharadita"}, "quantity": "1", "siboAlert": false}, {"name": {"en": "White Pepper", "es": "Pimienta Blanca"}, "unit": {"en": "teaspoon", "es": "cucharadita"}, "quantity": "1", "siboAlert": false}, {"name": {"en": "Nutmeg", "es": "Nuez Moscada"}, "unit": {"en": "tablespoon", "es": "cucharada"}, "quantity": "1", "siboAlert": true}]', '[{"type": "active", "order": 1, "instruction": {"en": "Wash the rice, drain it, and toast it with olive oil.", "es": "Lavar el arroz, escurrirlo y gratinarlo con aceite de oliva."}, "durationMinutes": 5}, {"type": "active", "order": 2, "instruction": {"en": "Add 4 cups of water and a pinch of sea salt, stir, and cover the pot.", "es": "Agregar 4 tazas de agua y una pizca de sal marina, revolver y tapar la olla."}, "durationMinutes": 2}, {"type": "passive", "order": 3, "instruction": {"en": "Cook over low heat for 20 minutes without uncovering.", "es": "Cocinar a fuego mínimo por 20 minutos sin destapar."}, "durationMinutes": 20}, {"type": "active", "order": 4, "instruction": {"en": "Sauté the carrots first, then the other vegetables, leaving them al dente.", "es": "Sofreír primero la zanahoria, luego los demás vegetales, dejándolos al dente."}, "durationMinutes": 10}, {"type": "active", "order": 5, "instruction": {"en": "Add the vegetable broth powder and spices, stir, and remove from heat.", "es": "Agregar el caldo en polvo y los condimentos, revolver y retirar del fuego."}, "durationMinutes": 3}, {"type": "active", "order": 6, "instruction": {"en": "Mix with the rice.", "es": "Mezclar con el arroz."}, "durationMinutes": 2}]', '[{"en": "vegano", "es": "vegano"}, {"en": "Vegetarian", "es": "Vegetariano"}, {"en": "arroz", "es": "arroz"}]', '/public/recipes/1775498679723.jpg', '1775498679723.jpg', 'caution', '["Nuez Moscada"]', 'ocr_image', 'https://api.telegram.org/file/bot8247874972:AAE84_Vvg3dQOX1gz8-L0ijOFBVyBmFD86w/photos/file_7.jpg', 'published', NULL, '2026-04-06 18:04:39.731+00', '2026-04-06 18:04:44.9+00', NULL);
